update public.study_materials
set body_md=replace(body_md,
'## 1. Fontes normativas do edital
O programa indica quatro diplomas centrais:
- Lei Federal nº 14.735/2023 — Lei Orgânica Nacional das Polícias Civis.
- Lei Complementar Estadual nº 129/2004 — Lei Orgânica da Polícia Civil e Estatuto dos Policiais Civis do Acre.
- Lei Estadual nº 2.250/2009.
- Lei Complementar Estadual nº 39/1993 — regime jurídico dos servidores públicos civis do Estado do Acre, nos dispositivos aplicáveis.',
'## 1. Fontes normativas do edital
O programa de Legislação Institucional do Anexo III abrange:
- Constituição Federal de 1988, art. 144, e Constituição do Estado do Acre, dispositivos sobre segurança pública e Polícia Civil.
- Lei Federal nº 14.735/2023 — Lei Orgânica Nacional das Polícias Civis.
- Lei Federal nº 12.830/2013 — investigação criminal conduzida pelo delegado.
- Lei Federal nº 13.675/2018 — PNSPDS e Sistema Único de Segurança Pública (Susp).
- Lei Complementar Estadual nº 129/2004 — Lei Orgânica da Polícia Civil e Estatuto dos Policiais Civis do Acre.
- Lei Estadual nº 2.250/2009 — Plano de Cargos, Carreiras e Remuneração da PCAC.
- Lei Complementar Estadual nº 39/1993 — direitos, deveres, regime disciplinar, sindicância e PAD nos dispositivos aplicáveis.

As aulas específicas sobre a Lei nº 12.830/2013, a Lei nº 13.675/2018 e as Constituições Federal e do Acre complementam o mapa inicial desta disciplina.')
where slug='pcac-2026-legislacao-institucional-policia-civil-acre';

update public.syllabus_topics
set topic_text='Constituição Federal de 1988, art. 144; Constituição do Estado do Acre, dispositivos relativos à segurança pública e à Polícia Civil; Lei Federal nº 14.735/2023 (Lei Orgânica Nacional das Polícias Civis): princípios, diretrizes, competências, organização, atribuições do delegado de polícia, garantias, prerrogativas, direitos, deveres e vedações; Lei Federal nº 12.830/2013 (investigação criminal conduzida pelo delegado de polícia); Lei Federal nº 13.675/2018 (Sistema Único de Segurança Pública — SUSP e Política Nacional de Segurança Pública e Defesa Social); Lei Complementar Estadual nº 129/2004 e alterações (Lei Orgânica da Polícia Civil do Estado do Acre): estrutura, organização, competências, carreira de delegado, direitos, deveres e regime disciplinar; Lei Estadual nº 2.250/2009 e alterações (PCCR da Polícia Civil do Estado do Acre): ingresso, progressão e promoção; Lei Complementar Estadual nº 39/1993 e alterações, nos dispositivos aplicáveis: direitos, deveres, regime disciplinar, sindicância e processo administrativo disciplinar.'
where id='d204d14f-8aa6-4c57-92ad-3fb3c3e901f1';

insert into public.study_materials
(slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,law_version_checked_at,content_status,reviewed_at,updated_at,flashcards,quiz,legal_review)
select x.slug,'Legislação Institucional',x.topic_label,x.sort_order,x.title,x.summary,x.body_md,'PC-AC 2026',1,x.source_note,x.legal_basis,now(),'active',now(),now(),x.flashcards,x.quiz,x.legal_review
from jsonb_to_recordset($materials$[{"slug":"pcac-2026-lei12830-investigacao-delegado-adi5043","title":"Lei nº 12.830/2013: investigação criminal conduzida pelo delegado","topic_label":"Lei Federal nº 12.830/2013 — condução da investigação e indiciamento","sort_order":23,"body_md":"# Lei nº 12.830/2013 — investigação criminal conduzida pelo delegado\n\n## 1. Objeto e natureza das funções\n\nA Lei nº 12.830/2013 disciplina a investigação criminal conduzida pelo delegado de polícia. O art. 2º afirma que as funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado têm natureza jurídica, são essenciais e exclusivas de Estado.\n\n**Atenção à diferença:** a natureza de função estatal essencial e exclusiva não significa que toda investigação criminal seja monopólio da Polícia Civil. O STF, na ADI 5.043, afastou a interpretação de que o art. 2º, § 1º, torne a investigação criminal privativa ou exclusiva do delegado ou da polícia. O Ministério Público, as CPIs e outras autoridades também podem exercer competências investigativas previstas na Constituição e nas leis.\n\n## 2. Condução e objeto da investigação — art. 2º, § 1º\n\nNa condição de autoridade policial, cabe ao delegado conduzir a investigação criminal por inquérito policial ou outro procedimento previsto em lei. O objetivo é apurar:\n- as circunstâncias do fato;\n- a materialidade da infração;\n- a autoria.\n\nA palavra **conduzir** indica direção do procedimento policial, mas não autoriza concluir que toda atividade investigativa estatal seja exclusiva da polícia.\n\n## 3. Poder de requisição — art. 2º, § 2º\n\nDurante a investigação criminal, o delegado pode requisitar perícias, informações, documentos e dados que interessem à apuração dos fatos. A requisição deve guardar relação com a investigação e respeitar as reservas legais e constitucionais aplicáveis a dados protegidos.\n\n## 4. Avocação e redistribuição — art. 2º, § 4º\n\nInquérito ou procedimento investigatório em curso somente pode ser avocado ou redistribuído por superior hierárquico mediante **despacho fundamentado**, por:\n1. motivo de interesse público; ou\n2. inobservância dos procedimentos regulamentares da corporação que prejudique a eficácia da investigação.\n\nNão é autorização para troca arbitrária de responsável.\n\n## 5. Remoção e indiciamento — art. 2º, §§ 5º e 6º\n\n- A remoção do delegado deve ocorrer por ato fundamentado.\n- O indiciamento é privativo do delegado de polícia.\n- O indiciamento deve ser formalizado por ato fundamentado, após análise técnico-jurídica do fato, indicando autoria, materialidade e circunstâncias.\n\n**Pegadinha:** a condução da investigação não é exclusiva da polícia segundo o STF; o indiciamento formal previsto no § 6º, por outro lado, é atribuição privativa do delegado.\n\n## 6. Requisito do cargo — art. 3º\n\nO cargo de delegado de polícia é privativo de bacharel em Direito. A lei também prevê tratamento protocolar equivalente ao dispensado às autoridades e profissionais indicados no próprio dispositivo.\n\n## 7. Quadro de memorização\n\n| Tema | Regra |\n|---|---|\n| Funções de polícia judiciária | Natureza jurídica, essenciais e exclusivas de Estado |\n| Condução do inquérito policial | Delegado, como autoridade policial |\n| Investigação criminal em sentido amplo | Não é monopólio da polícia (STF, ADI 5.043) |\n| Requisição | Perícias, informações, documentos e dados pertinentes |\n| Avocação/redistribuição | Superior hierárquico + despacho fundamentado + motivo legal |\n| Remoção | Ato fundamentado |\n| Indiciamento | Privativo do delegado, por ato fundamentado |\n| Formação | Bacharelado em Direito para o cargo de delegado |\n\n## 8. Como a IDECAN pode cobrar\n\n1. Trocar “privativo” por “não exclusivo” ao falar de investigação criminal: lembre-se da ADI 5.043.\n2. Dizer que o delegado pode requisitar qualquer dado sem limites: a requisição deve ser pertinente e respeitar reservas legais.\n3. Omitir a necessidade de fundamentação na avocação, redistribuição ou remoção.\n4. Afirmar que o indiciamento é ato do Ministério Público ou do juiz: o art. 2º, § 6º, o atribui privativamente ao delegado.\n5. Confundir direção do inquérito policial com exclusividade de toda investigação criminal.\n\n## 9. Fontes oficiais\n- Lei nº 12.830/2013, arts. 1º a 4º.\n- STF, ADI 5.043: interpretação do art. 2º, § 1º, sem exclusividade policial na investigação criminal.\n- Edital nº 001 SEAD/PCAC/2026, Anexo III.","source_note":"Edital nº 001 SEAD/PCAC/2026, Anexo III. Lei nº 12.830/2013, texto do Senado Federal; STF, ADI 5.043, julgamento de 28/03/2025. Conferido em 14/11/2026.","legal_basis":[{"title":"Lei nº 12.830/2013 — Senado Federal","url":"https://legis.senado.leg.br/norma/591278/publicacao/15636365"},{"title":"STF — ADI 5.043, inteiro teor","url":"https://portal.stf.jus.br/jurisprudencia/obterInteiroTeor.asp?idDocumento=785761791"}],"flashcards":[{"f":"O que disciplina a Lei nº 12.830/2013?","b":"A investigação criminal conduzida pelo delegado de polícia."},{"f":"Quais são os objetivos do inquérito ou procedimento conduzido pelo delegado, segundo o art. 2º, § 1º?","b":"Apurar as circunstâncias, a materialidade e a autoria das infrações penais."},{"f":"A investigação criminal é exclusiva da Polícia Civil?","b":"Não. O STF, na ADI 5.043, afastou a interpretação de exclusividade policial; MP, CPIs e outras autoridades podem investigar nos limites de suas competências."},{"f":"O que o delegado pode requisitar durante a investigação, conforme art. 2º, § 2º?","b":"Perícias, informações, documentos e dados que interessem à apuração dos fatos, respeitadas as reservas legais."},{"f":"Quem pode avocar ou redistribuir inquérito em curso?","b":"Superior hierárquico, mediante despacho fundamentado e por motivo de interesse público ou inobservância regulamentar que prejudique a eficácia da investigação."},{"f":"Como deve ocorrer a remoção do delegado?","b":"Somente por ato fundamentado."},{"f":"Quem realiza o indiciamento e como?","b":"É ato privativo do delegado, fundamentado em análise técnico-jurídica e com indicação de autoria, materialidade e circunstâncias."},{"f":"Qual formação é exigida para o cargo de delegado?","b":"Bacharelado em Direito."}],"quiz":[{"q":"A Lei nº 12.830/2013 atribui natureza jurídica às funções de polícia judiciária e apuração de infrações penais exercidas pelo delegado.","a":true,"why":"O art. 2º expressamente qualifica essas funções como de natureza jurídica, essenciais e exclusivas de Estado."},{"q":"Segundo o STF na ADI 5.043, o art. 2º, § 1º, torna privativa do delegado toda e qualquer investigação criminal.","a":false,"why":"O STF declarou inconstitucional a interpretação que atribua exclusividade ao delegado. O Ministério Público, CPIs e outras autoridades também podem investigar quando houver competência constitucional ou legal."},{"q":"Durante a investigação, o delegado pode requisitar perícias, informações, documentos e dados que interessem à apuração.","a":true,"why":"É a previsão do art. 2º, § 2º. A pertinência com a apuração e as reservas legais de sigilo continuam relevantes."},{"q":"Um superior hierárquico pode redistribuir inquérito em curso por simples conveniência pessoal, sem despacho fundamentado.","a":false,"why":"O art. 2º, § 4º, exige despacho fundamentado e motivo de interesse público ou inobservância regulamentar que prejudique a eficácia da investigação."},{"q":"O indiciamento é privativo do delegado e deve ser formalizado por ato fundamentado.","a":true,"why":"O art. 2º, § 6º, exige análise técnico-jurídica do fato e indicação de autoria, materialidade e circunstâncias."},{"q":"A remoção do delegado pode ser feita sem motivação, por ser ato discricionário.","a":false,"why":"O art. 2º, § 5º, determina que a remoção se dê somente por ato fundamentado."},{"q":"A lei exige bacharelado em Direito para o cargo de delegado de polícia.","a":true,"why":"O art. 3º estabelece que o cargo é privativo de bacharel em Direito."},{"q":"A exclusividade estatal das funções de polícia judiciária significa que nenhuma outra instituição pode realizar investigação criminal.","a":false,"why":"Não confunda natureza de função estatal com monopólio de investigação. A ADI 5.043 reconheceu a possibilidade de investigações por outros órgãos dentro de suas competências."}],"summary":"Lei nº 12.830/2013: investigação criminal conduzida pelo delegado — conteúdo específico do edital PC-AC 2026","legal_review":{"status":"reviewed_against_official_primary_sources","review_date":"2026-11-14","notes":"Conferência da legislação federal e estadual indicada no Anexo III, com atualização jurisprudencial quando aplicável."}},{"slug":"pcac-2026-lei13675-susp-politica-seguranca","title":"Lei nº 13.675/2018: Política Nacional de Segurança Pública e SUSP","topic_label":"Lei Federal nº 13.675/2018 — PNSPDS e Sistema Único de Segurança Pública","sort_order":24,"body_md":"# Lei nº 13.675/2018 — PNSPDS e Sistema Único de Segurança Pública\n\n## 1. Objeto da lei\n\nA Lei nº 13.675/2018 disciplina a organização e o funcionamento dos órgãos responsáveis pela segurança pública, cria a Política Nacional de Segurança Pública e Defesa Social (PNSPDS) e institui o Sistema Único de Segurança Pública (Susp).\n\nA ideia central é a **integração cooperativa**: os órgãos mantêm suas competências legais, mas devem atuar de forma coordenada, sistêmica e harmônica.\n\n## 2. Política Nacional de Segurança Pública e Defesa Social\n\nA PNSPDS estabelece diretrizes, princípios, objetivos e estratégias para orientar a atuação dos entes federativos e dos órgãos de segurança pública e defesa social.\n\nEntre os pontos de estudo estão:\n- respeito aos direitos humanos e às garantias fundamentais;\n- proteção da vida, do patrimônio e do meio ambiente;\n- participação e controle social;\n- resolução pacífica de conflitos;\n- eficiência na prevenção e no controle das infrações;\n- integração e compartilhamento de informações;\n- valorização e proteção dos profissionais de segurança pública.\n\n**Atenção:** política nacional é o conjunto de princípios, diretrizes e objetivos; Susp é o sistema de integração dos órgãos e instituições que atuam na segurança pública.\n\n## 3. Sistema Único de Segurança Pública — art. 9º\n\nO art. 9º institui o Susp. Os integrantes atuam dentro dos limites de suas respectivas competências, de forma cooperativa, sistêmica e harmônica.\n\n### Integrantes estratégicos — art. 9º, § 1º\n1. União, Estados, Distrito Federal e Municípios, por meio dos respectivos Poderes Executivos;\n2. Conselhos de Segurança Pública e Defesa Social dos três níveis federativos.\n\n### Integrantes operacionais — art. 9º, § 2º\nO rol legal inclui, entre outros:\n- Polícia Federal e Polícia Rodoviária Federal;\n- Polícias Civis;\n- Polícias Militares e Corpos de Bombeiros Militares;\n- Guardas Municipais;\n- órgãos do sistema penitenciário;\n- institutos oficiais de criminalística, medicina legal e identificação;\n- Senasp, secretarias estaduais de segurança pública ou congêneres;\n- órgãos de proteção e defesa civil, política sobre drogas;\n- agentes de trânsito, guarda portuária e polícia legislativa, conforme a legislação.\n\nO texto contém incisos vetados e alterações posteriores. Para prova literal, observe a redação vigente do § 2º, inclusive a inclusão da polícia legislativa pela Lei nº 14.531/2023.\n\n## 4. Integração e coordenação — art. 10\n\nA integração e coordenação dos integrantes do Susp ocorre dentro das respectivas competências, por instrumentos como:\n- operações planejadas e executadas de forma integrada;\n- estratégias comuns de prevenção e controle qualificado de infrações;\n- aceitação mútua de registros de ocorrência;\n- compartilhamento de informações;\n- intercâmbio de conhecimentos técnicos e científicos;\n- integração de sistemas de inteligência e de investigação;\n- capacitação e ações conjuntas.\n\n**Pegadinha:** integração não significa fusão institucional, subordinação automática de uma polícia a outra ou transferência irrestrita de atribuições.\n\n## 5. Funcionamento dos sistemas estaduais e municipais\n\nO art. 9º, § 4º, atribui aos sistemas estaduais, distrital e municipais a implementação dos respectivos programas, ações e projetos de segurança pública, com liberdade de organização e funcionamento, respeitada a Lei nº 13.675/2018.\n\nPortanto, o Susp articula a atuação nacional sem apagar a autonomia organizacional dos entes federativos.\n\n## 6. Relação com a Polícia Civil do Acre\n\nA Polícia Civil integra operacionalmente o Susp. Isso significa cooperação e integração com outros órgãos, preservadas as competências constitucionais e legais da PCAC: polícia judiciária e apuração das infrações penais, exceto as militares e ressalvada a competência da União.\n\nA atuação integrada pode envolver operações conjuntas, troca de informações, interoperabilidade de sistemas e capacitação, sem transformar a Polícia Civil em órgão subordinado a outro integrante operacional.\n\n## 7. Comparação que cai em prova\n\n| PNSPDS | Susp |\n|---|---|\n| Política pública nacional | Sistema de integração |\n| Define princípios, diretrizes e objetivos | Articula órgãos e instituições |\n| Orienta planejamento e ações | Promove cooperação operacional |\n| Não é uma polícia | Não substitui as polícias |\n\n## 8. Pegadinhas da IDECAN\n\n- A Polícia Civil é integrante operacional do Susp, não integrante estratégico.\n- União, Estados, DF e Municípios, por seus Executivos, são integrantes estratégicos.\n- Os Conselhos de Segurança Pública e Defesa Social também são estratégicos.\n- A integração respeita as competências de cada órgão.\n- Susp não significa unificação das polícias nem hierarquia entre integrantes.\n- A Lei nº 13.675/2018 institui tanto a PNSPDS quanto o Susp.\n\n## 9. Fontes oficiais\n- Lei nº 13.675/2018, especialmente arts. 1º a 10.\n- Lei nº 14.531/2023, alterações no rol de integrantes do Susp.\n- Edital nº 001 SEAD/PCAC/2026, Anexo III.","source_note":"Edital nº 001 SEAD/PCAC/2026, Anexo III. Lei nº 13.675/2018, texto e histórico legislativo do Senado Federal; art. 9º conferido em normas.leg.br; alterações da Lei nº 14.531/2023. Conferido em 14/11/2026.","legal_basis":[{"title":"Lei nº 13.675/2018 — Senado Federal","url":"https://legis.senado.leg.br/norma/27394952"},{"title":"Lei nº 13.675/2018 — art. 9º, Normas Legais","url":"https://normas.leg.br/?urn=urn%3Alex%3Abr%3Afederal%3Alei%3A2018-06-11%3B13675%21art9"},{"title":"Lei nº 14.531/2023 — alterações na Lei nº 13.675/2018","url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14531.htm"}],"flashcards":[{"f":"O que a Lei nº 13.675/2018 institui?","b":"A Política Nacional de Segurança Pública e Defesa Social (PNSPDS) e o Sistema Único de Segurança Pública (Susp)."},{"f":"Qual a diferença entre PNSPDS e Susp?","b":"A PNSPDS orienta a política por princípios, diretrizes e objetivos; o Susp articula e integra órgãos e instituições."},{"f":"Como os integrantes do Susp devem atuar?","b":"Dentro dos limites de suas competências, de forma cooperativa, sistêmica e harmônica."},{"f":"Quem são os integrantes estratégicos do Susp?","b":"União, Estados, Distrito Federal e Municípios por seus Executivos, além dos Conselhos de Segurança Pública e Defesa Social dos três entes."},{"f":"A Polícia Civil é integrante estratégico ou operacional do Susp?","b":"É integrante operacional, conforme art. 9º, § 2º, IV."},{"f":"Cite exemplos de integrantes operacionais do Susp.","b":"Polícias Civil, Federal e Rodoviária Federal; PMs e Bombeiros; Guardas Municipais; sistema penitenciário; institutos oficiais de perícia e identificação, entre outros."},{"f":"O que o art. 9º, § 4º, assegura aos sistemas estaduais, distrital e municipais?","b":"Responsabilidade pela implementação de programas, ações e projetos, com liberdade de organização e funcionamento, respeitada a lei."},{"f":"A integração do Susp elimina as competências próprias de cada órgão?","b":"Não. A integração ocorre dentro dos limites das competências legais de cada integrante."}],"quiz":[{"q":"A Lei nº 13.675/2018 instituiu o Susp e criou a PNSPDS.","a":true,"why":"A ementa e o art. 1º da lei estabelecem esses dois pilares: política nacional e sistema de integração."},{"q":"A Polícia Civil é integrante estratégico do Susp.","a":false,"why":"As Polícias Civis aparecem no rol dos integrantes operacionais, no art. 9º, § 2º, IV. Integrantes estratégicos são os entes federativos por seus Executivos e os Conselhos."},{"q":"União, Estados, Distrito Federal e Municípios, por meio de seus respectivos Poderes Executivos, são integrantes estratégicos do Susp.","a":true,"why":"É a previsão do art. 9º, § 1º, I. O dispositivo também inclui os Conselhos de Segurança Pública e Defesa Social."},{"q":"Os órgãos integrantes do Susp atuam de forma cooperativa, sistêmica e harmônica, dentro dos limites de suas competências.","a":true,"why":"Essa é a regra do caput do art. 9º. A integração não autoriza extrapolar competências."},{"q":"A integração no Susp significa que uma Polícia Civil estadual fica hierarquicamente subordinada à Polícia Federal.","a":false,"why":"A lei prevê cooperação e coordenação, não subordinação automática entre órgãos. Cada integrante preserva suas competências e sua estrutura."},{"q":"Os sistemas estaduais, distrital e municipais têm responsabilidade pela implementação de seus programas, ações e projetos de segurança pública.","a":true,"why":"O art. 9º, § 4º, atribui essa responsabilidade aos sistemas locais, com liberdade de organização e funcionamento, respeitada a lei."},{"q":"A PNSPDS é uma instituição policial com poder de polícia próprio.","a":false,"why":"A PNSPDS é uma política pública nacional, com princípios, diretrizes e objetivos; não é uma corporação policial."},{"q":"A Lei nº 14.531/2023 incluiu a polícia legislativa no rol de integrantes operacionais do Susp.","a":true,"why":"A alteração acrescentou o inciso XVII ao art. 9º, § 2º, referente à polícia legislativa prevista na Constituição Federal."}],"summary":"Lei nº 13.675/2018: Política Nacional de Segurança Pública e SUSP — conteúdo específico do edital PC-AC 2026","legal_review":{"status":"reviewed_against_official_primary_sources","review_date":"2026-11-14","notes":"Conferência da legislação federal e estadual indicada no Anexo III, com atualização jurisprudencial quando aplicável."}},{"slug":"pcac-2026-constituicao-seguranca-publica-art144-acre","title":"Constituições Federal e do Acre: segurança pública e Polícia Civil","topic_label":"CF/1988, art. 144, e Constituição do Acre, arts. 129 a 133","sort_order":25,"body_md":"# Segurança pública nas Constituições Federal e do Acre\n\n## 1. Constituição Federal — art. 144\n\nO caput do art. 144 estabelece que a segurança pública é dever do Estado, direito e responsabilidade de todos. Sua finalidade é preservar a ordem pública e a incolumidade das pessoas e do patrimônio.\n\nO artigo enumera os órgãos responsáveis pela segurança pública. Para a prova, memorize as funções constitucionais e não confunda polícia judiciária/investigativa com polícia ostensiva.\n\n### Polícia Civil — art. 144, § 4º\n\nÀs Polícias Civis, dirigidas por delegados de polícia de carreira, incumbem, ressalvada a competência da União, as funções de polícia judiciária e a apuração de infrações penais, exceto as militares.\n\n### Polícia Militar — art. 144, § 5º\n\nÀs Polícias Militares cabem a polícia ostensiva e a preservação da ordem pública. Aos Corpos de Bombeiros Militares cabem, além das atribuições definidas em lei, a execução de atividades de defesa civil.\n\n### Polícia Penal — art. 144, § 5º-A\n\nÀs polícias penais, vinculadas ao órgão administrador do sistema penal da unidade federativa a que pertencem, cabe a segurança dos estabelecimentos penais.\n\n### Subordinação e organização\n\nO § 6º subordina as Polícias Civis, Polícias Militares e Corpos de Bombeiros Militares, além das polícias penais estaduais e distrital, aos Governadores dos Estados, do DF e dos Territórios, nos termos constitucionais. O § 7º determina que a lei discipline a organização e o funcionamento dos órgãos responsáveis pela segurança pública, de maneira a garantir a eficiência de suas atividades.\n\n## 2. Constituição do Estado do Acre — defesa social e segurança pública\n\nO Título IV trata da Defesa do Estado. O art. 129 define a Defesa Social como dever do Estado e responsabilidade de todos, organizada sistemicamente para:\n- garantir a segurança pública e a manutenção da ordem;\n- proteger cidadãos, sociedade e bens públicos e particulares;\n- prestar defesa civil em calamidades e sinistros;\n- promover integração social para prevenir violência e criminalidade.\n\nO art. 131, com a redação da Emenda Constitucional estadual nº 63/2022, enumera os órgãos da segurança pública estadual:\n1. Polícia Civil;\n2. Polícia Militar e Corpo de Bombeiros Militar;\n3. Polícia Penal;\n4. Instituto Socioeducativo do Estado do Acre.\n\n**Atenção à atualização:** não memorize versões antigas do art. 131. A EC nº 63/2022 alterou a composição constitucional estadual e revogou a redação anterior.\n\n## 3. Polícia Civil do Acre — art. 133\n\nO art. 133 caracteriza a Polícia Civil como instituição permanente do Poder Público, dirigida por Delegado de Polícia de carreira e organizada pelos princípios da hierarquia e disciplina.\n\nCompete-lhe, ressalvada a competência da União:\n- exercer as funções de polícia judiciária;\n- apurar infrações penais em todo o território estadual;\n- excetuar as infrações penais militares.\n\nO texto estadual também enumera atividades privativas da Polícia Civil:\nI — polícia técnico-científica;\nII — processamento e arquivo de identificação civil e criminal;\nIII — registro e licenciamento de veículos automotores e habilitação de seus condutores;\nIV — licenciamento de porte de armas.\n\n**Cuidado na prova:** o texto do art. 133 deve ser estudado como redação constitucional estadual publicada no portal oficial, mas sua aplicação deve ser harmonizada com a Constituição Federal, com as competências federais e com a legislação nacional superveniente. Não transforme a enumeração estadual em autorização para contrariar competências da União.\n\n## 4. Comparação essencial\n\n| Polícia/órgão | Função constitucional central |\n|---|---|\n| Polícia Civil | Polícia judiciária e apuração de infrações penais, exceto militares |\n| Polícia Militar | Polícia ostensiva e preservação da ordem pública |\n| Corpo de Bombeiros Militar | Defesa civil e atribuições legais |\n| Polícia Penal | Segurança dos estabelecimentos penais |\n| Polícia Federal | Polícia judiciária da União e competências constitucionais federais |\n\n## 5. Pegadinhas da IDECAN\n\n- Segurança pública é dever do Estado, direito e responsabilidade de todos.\n- A Polícia Civil não exerce polícia ostensiva como função constitucional típica.\n- A Polícia Militar não preside inquérito de crime comum por ser polícia judiciária.\n- A Polícia Civil apura infrações penais, exceto as militares, ressalvada a competência da União.\n- O art. 131 da Constituição do Acre foi alterado pela EC nº 63/2022: o ISE aparece no inciso IV.\n- Não confunda Polícia Penal com Polícia Civil ou com o sistema socioeducativo.\n\n## 6. Fontes oficiais\n- Constituição Federal, art. 144, texto compilado.\n- Constituição do Estado do Acre, arts. 129 a 133.\n- Emenda Constitucional do Acre nº 63/2022.\n- Edital nº 001 SEAD/PCAC/2026, Anexo III.","source_note":"Edital nº 001 SEAD/PCAC/2026, Anexo III. Constituição Federal compilada; Constituição do Estado do Acre no Portal LEGIS; Emenda Constitucional estadual nº 63/2022. Conferido em 14/11/2026. O art. 133 estadual deve ser harmonizado com competências federais e normas supervenientes.","legal_basis":[{"title":"Constituição Federal — texto compilado","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"},{"title":"Constituição do Estado do Acre — Portal LEGIS","url":"https://www.legis.ac.gov.br/detalhar_constituicao"},{"title":"Emenda Constitucional do Acre nº 63/2022","url":"https://legis.ac.gov.br/detalhar_emendas/64"}],"flashcards":[{"f":"Como o art. 144 define a segurança pública?","b":"Dever do Estado, direito e responsabilidade de todos, destinada à preservação da ordem pública e da incolumidade das pessoas e do patrimônio."},{"f":"Qual é a função constitucional central da Polícia Civil, segundo o art. 144, § 4º?","b":"Exercer funções de polícia judiciária e apurar infrações penais, exceto as militares, ressalvada a competência da União."},{"f":"Qual é a função constitucional central da Polícia Militar?","b":"Polícia ostensiva e preservação da ordem pública."},{"f":"A quem cabe a segurança dos estabelecimentos penais?","b":"Às polícias penais, conforme art. 144, § 5º-A, da Constituição Federal."},{"f":"Quais são os órgãos listados no art. 131 da Constituição do Acre após a EC nº 63/2022?","b":"Polícia Civil; Polícia Militar e Corpo de Bombeiros Militar; Polícia Penal; Instituto Socioeducativo do Estado do Acre."},{"f":"Como o art. 129 da Constituição do Acre define a Defesa Social?","b":"Como dever do Estado e responsabilidade de todos, organizada sistemicamente para segurança pública, defesa civil e prevenção da violência."},{"f":"Como o art. 133 caracteriza a Polícia Civil do Acre?","b":"Instituição permanente do Poder Público, dirigida por Delegado de Polícia de carreira e organizada segundo hierarquia e disciplina."},{"f":"Qual é a exceção expressa à apuração estadual de infrações penais pela Polícia Civil?","b":"As infrações penais militares, além da ressalva da competência da União."}],"quiz":[{"q":"A Constituição Federal define a segurança pública como dever do Estado, direito e responsabilidade de todos.","a":true,"why":"É a redação expressa do caput do art. 144. A finalidade é preservar a ordem pública e a incolumidade das pessoas e do patrimônio."},{"q":"À Polícia Civil cabem, como regra constitucional, a polícia ostensiva e a preservação da ordem pública.","a":false,"why":"Essas são funções constitucionais da Polícia Militar, conforme art. 144, § 5º. À Polícia Civil cabem polícia judiciária e apuração de infrações penais, exceto militares."},{"q":"A Polícia Civil exerce apuração de infrações penais, ressalvada a competência da União e excetuadas as infrações militares.","a":true,"why":"A regra consta do art. 144, § 4º, da Constituição Federal."},{"q":"A segurança dos estabelecimentos penais é atribuição constitucional das polícias penais.","a":true,"why":"O art. 144, § 5º-A, atribui às polícias penais a segurança dos estabelecimentos penais."},{"q":"Após a EC nº 63/2022, o art. 131 da Constituição do Acre inclui o Instituto Socioeducativo do Estado do Acre no inciso IV.","a":true,"why":"A EC nº 63/2022 alterou o art. 131 e passou a listar PC, PM/CBM, Polícia Penal e ISE. Redações anteriores não devem ser usadas como atuais."},{"q":"O art. 129 da Constituição do Acre trata a Defesa Social como dever exclusivo dos órgãos policiais.","a":false,"why":"O dispositivo a define como dever do Estado e responsabilidade de todos, incluindo defesa civil e integração social para prevenção da violência."},{"q":"A Polícia Civil do Acre é instituição permanente, dirigida por Delegado de Polícia de carreira, segundo o art. 133 estadual.","a":true,"why":"O art. 133 traz expressamente essa caracterização e os princípios da hierarquia e disciplina."},{"q":"O art. 144, § 4º, permite que a Polícia Civil estadual apure crimes militares comuns sempre que ocorram no território do Estado.","a":false,"why":"O § 4º exclui as infrações penais militares e ressalva a competência da União. O local do fato não elimina essas exceções."}],"summary":"Constituições Federal e do Acre: segurança pública e Polícia Civil — conteúdo específico do edital PC-AC 2026","legal_review":{"status":"reviewed_against_official_primary_sources","review_date":"2026-11-14","notes":"Conferência da legislação federal e estadual indicada no Anexo III, com atualização jurisprudencial quando aplicável."}}]$materials$::jsonb)
