insert into public.curated_question_catalog
(source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,didactic_provenance)
select source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,didactic_provenance
from jsonb_to_recordset($questions$[{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-301-12830-investigacao-nao-exclusiva","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"Lei nº 12.830/2013 e ADI 5.043: investigação não exclusiva","tested_topic":"Lei nº 12.830/2013, art. 2º, § 1º; STF, ADI 5.043","difficulty":"alta","official_answer":"C","question_text":"Uma questão afirma que, por força do art. 2º, § 1º, da Lei nº 12.830/2013, somente o delegado de polícia pode conduzir qualquer investigação criminal no Brasil. À luz do entendimento do STF na ADI 5.043, assinale a alternativa correta.\n\nA) A afirmação está correta, pois a investigação criminal é monopólio constitucional da Polícia Civil.\nB) A afirmação está correta apenas para crimes estaduais.\nC) A interpretação de exclusividade foi afastada pelo STF; outros órgãos, como o Ministério Público e CPIs, podem investigar dentro de suas competências constitucionais e legais.\nD) O STF declarou que o delegado não pode conduzir inquérito policial.\nE) O STF transferiu a presidência de todos os inquéritos ao Ministério Público.","explanation":"O STF, na ADI 5.043, declarou inconstitucional a interpretação do art. 2º, § 1º, que atribua privativamente ou exclusivamente ao delegado a condução de investigações criminais. Isso não elimina a atribuição do delegado de conduzir o inquérito policial, mas afasta o monopólio de toda investigação criminal.","legal_basis":["Lei nº 12.830/2013, art. 2º, § 1º","STF, ADI 5.043"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Lei nº 12.830/2013, art. 2º, § 1º","STF, ADI 5.043"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-302-12830-avocacao-redistribuicao","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"Lei nº 12.830/2013: avocação e redistribuição","tested_topic":"Lei nº 12.830/2013, art. 2º, § 4º","difficulty":"alta","official_answer":"D","question_text":"Um superior hierárquico pretende redistribuir um inquérito policial em curso. Segundo o art. 2º, § 4º, da Lei nº 12.830/2013, a medida:\n\nA) pode ocorrer livremente, por ordem verbal.\nB) depende de autorização judicial em todos os casos.\nC) somente pode ocorrer por requerimento do investigado.\nD) exige despacho fundamentado e motivo de interesse público ou inobservância de procedimento regulamentar que prejudique a eficácia da investigação.\nE) é vedada em qualquer hipótese.","explanation":"O § 4º exige despacho fundamentado do superior hierárquico e uma das hipóteses legais: interesse público ou inobservância de procedimentos regulamentares da corporação que prejudique a eficácia da investigação. Não se admite redistribuição arbitrária ou verbal.","legal_basis":["Lei nº 12.830/2013, art. 2º, § 4º"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Lei nº 12.830/2013, art. 2º, § 4º"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-303-12830-indiciamento","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"Lei nº 12.830/2013: ato de indiciamento","tested_topic":"Lei nº 12.830/2013, art. 2º, § 6º","difficulty":"média","official_answer":"A","question_text":"De acordo com a Lei nº 12.830/2013, o indiciamento:\n\nA) é privativo do delegado de polícia e deve ser formalizado por ato fundamentado, mediante análise técnico-jurídica que indique autoria, materialidade e circunstâncias.\nB) é ato privativo do Ministério Público.\nC) pode ser realizado por qualquer agente policial, sem fundamentação.\nD) é ato exclusivo do juiz, na sentença.\nE) dispensa indicação de materialidade quando houver confissão.","explanation":"O art. 2º, § 6º, define o indiciamento como ato privativo do delegado de polícia, que deve ser fundamentado e resultar de análise técnico-jurídica, indicando autoria, materialidade e circunstâncias do fato.","legal_basis":["Lei nº 12.830/2013, art. 2º, § 6º"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Lei nº 12.830/2013, art. 2º, § 6º"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-304-12830-requisicao","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"Lei nº 12.830/2013: requisição durante a investigação","tested_topic":"Lei nº 12.830/2013, art. 2º, § 2º","difficulty":"média","official_answer":"B","question_text":"Durante a investigação criminal, a autoridade policial necessita de documentos e perícia relacionados ao fato. Nos termos do art. 2º, § 2º, da Lei nº 12.830/2013, cabe ao delegado:\n\nA) apenas solicitar informalmente informações ao investigado.\nB) requisitar perícia, informações, documentos e dados que interessem à apuração dos fatos, observadas as reservas legais aplicáveis.\nC) requisitar qualquer conteúdo protegido por sigilo, sem observar a Constituição ou a lei.\nD) obter autorização legislativa para cada perícia.\nE) transferir automaticamente a requisição ao juiz.","explanation":"O § 2º autoriza o delegado a requisitar perícias, informações, documentos e dados que interessem à apuração. A requisição não afasta sigilos e reservas constitucionais ou legais que exijam procedimento ou autorização próprios.","legal_basis":["Lei nº 12.830/2013, art. 2º, § 2º"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Lei nº 12.830/2013, art. 2º, § 2º"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-305-susp-integrantes-estrategicos","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"SUSP: integrantes estratégicos","tested_topic":"Lei nº 13.675/2018, art. 9º, § 1º","difficulty":"média","official_answer":"E","question_text":"Conforme o art. 9º, § 1º, da Lei nº 13.675/2018, são integrantes estratégicos do Susp:\n\nA) Polícia Civil, Polícia Militar e Corpo de Bombeiros.\nB) Polícia Federal, Polícia Rodoviária Federal e Guardas Municipais.\nC) apenas os Conselhos de Segurança Pública.\nD) institutos de criminalística e órgãos do sistema penitenciário.\nE) União, Estados, Distrito Federal e Municípios, por seus Poderes Executivos, e os Conselhos de Segurança Pública e Defesa Social dos três entes federativos.","explanation":"O § 1º classifica como estratégicos os entes federativos, por meio dos respectivos Poderes Executivos, e os Conselhos de Segurança Pública e Defesa Social. As polícias e demais instituições aparecem como integrantes operacionais no § 2º.","legal_basis":["Lei nº 13.675/2018, art. 9º, § 1º"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Lei nº 13.675/2018, art. 9º, § 1º"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-306-susp-policia-civil-operacional","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"SUSP: classificação da Polícia Civil","tested_topic":"Lei nº 13.675/2018, art. 9º, § 2º, IV","difficulty":"fácil","official_answer":"A","question_text":"No Sistema Único de Segurança Pública, a Polícia Civil é classificada como:\n\nA) integrante operacional.\nB) integrante estratégico.\nC) órgão central do Susp.\nD) conselho de segurança pública.\nE) entidade privada colaboradora.","explanation":"O art. 9º, § 2º, IV, inclui expressamente as Polícias Civis entre os integrantes operacionais. Os integrantes estratégicos são os entes federativos por seus Executivos e os Conselhos de Segurança Pública e Defesa Social.","legal_basis":["Lei nº 13.675/2018, art. 9º, § 2º, IV"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Lei nº 13.675/2018, art. 9º, § 2º, IV"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-307-susp-integracao-competencias","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"SUSP: integração e limites de competência","tested_topic":"Lei nº 13.675/2018, art. 9º, caput e art. 10","difficulty":"alta","official_answer":"C","question_text":"A integração entre órgãos do Susp permite que uma instituição exerça livremente as atribuições legais de outra, independentemente de previsão normativa. Essa afirmação é:\n\nA) correta, porque o Susp unificou todas as polícias.\nB) correta, desde que haja convênio informal.\nC) incorreta, pois a cooperação e a coordenação ocorrem dentro dos limites das competências de cada integrante.\nD) correta apenas nas operações interestaduais.\nE) incorreta porque a Lei nº 13.675/2018 proíbe operações integradas.","explanation":"O art. 9º determina atuação cooperativa, sistêmica e harmônica, mas dentro dos limites das respectivas competências. O art. 10 prevê instrumentos de integração e coordenação, sem criar fusão institucional ou transferência irrestrita de atribuições.","legal_basis":["Lei nº 13.675/2018, arts. 9º e 10"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Lei nº 13.675/2018, arts. 9º e 10"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-308-susp-integrantes-operacionais-alteracoes","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"SUSP: integrantes operacionais e alteração de 2023","tested_topic":"Lei nº 13.675/2018, art. 9º, § 2º, XVII","difficulty":"média","official_answer":"D","question_text":"A Lei nº 14.531/2023 alterou o rol de integrantes operacionais do Susp para incluir expressamente:\n\nA) os Poderes Judiciários estaduais.\nB) as assembleias legislativas estaduais.\nC) os tribunais de contas municipais.\nD) a polícia legislativa prevista nos dispositivos constitucionais indicados no inciso XVII.\nE) exclusivamente as guardas patrimoniais privadas.","explanation":"A Lei nº 14.531/2023 acrescentou o inciso XVII ao § 2º do art. 9º, incluindo a polícia legislativa prevista no art. 27, § 3º, art. 51, IV, e art. 52, XIII, da Constituição Federal.","legal_basis":["Lei nº 13.675/2018, art. 9º, § 2º, XVII","Lei nº 14.531/2023"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Lei nº 13.675/2018, art. 9º, § 2º, XVII","Lei nº 14.531/2023"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-309-cf144-funcao-pc","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"CF, art. 144, § 4º: atribuição da Polícia Civil","tested_topic":"Constituição Federal, art. 144, § 4º","difficulty":"média","official_answer":"B","question_text":"Segundo o art. 144, § 4º, da Constituição Federal, às Polícias Civis, dirigidas por delegados de polícia de carreira, incumbem:\n\nA) polícia ostensiva e preservação da ordem pública.\nB) funções de polícia judiciária e apuração de infrações penais, exceto as militares, ressalvada a competência da União.\nC) segurança dos estabelecimentos penais.\nD) defesa civil em calamidades.\nE) policiamento ostensivo rodoviário federal.","explanation":"O § 4º atribui às Polícias Civis a polícia judiciária e a apuração de infrações penais, exceto as militares, ressalvada a competência da União. Polícia ostensiva é função da Polícia Militar; segurança penal cabe à Polícia Penal.","legal_basis":["Constituição Federal, art. 144, § 4º"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Constituição Federal, art. 144, § 4º"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-310-ceacre-art131-ec63","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"Constituição do Acre: composição da segurança pública após EC 63/2022","tested_topic":"Constituição do Estado do Acre, art. 131; EC estadual nº 63/2022","difficulty":"média","official_answer":"A","question_text":"Após a Emenda Constitucional estadual nº 63/2022, o art. 131 da Constituição do Acre lista como órgãos da segurança pública:\n\nA) Polícia Civil; Polícia Militar e Corpo de Bombeiros Militar; Polícia Penal; Instituto Socioeducativo do Estado do Acre.\nB) Polícia Civil; Polícia Federal; Polícia Rodoviária Federal; Guarda Municipal.\nC) Polícia Civil e apenas Polícia Militar.\nD) Polícia Civil; Ministério Público; Defensoria Pública; Poder Judiciário.\nE) Polícia Civil; Polícia Penal; agentes de trânsito; guardas privadas.","explanation":"A EC nº 63/2022 alterou o art. 131 e consolidou o rol estadual em quatro incisos: Polícia Civil; Polícia Militar e Corpo de Bombeiros Militar; Polícia Penal; Instituto Socioeducativo do Estado do Acre. A redação anterior não deve ser memorizada como atual.","legal_basis":["Constituição do Estado do Acre, art. 131","Emenda Constitucional estadual nº 63/2022"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Constituição do Estado do Acre, art. 131","Emenda Constitucional estadual nº 63/2022"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-311-ceacre-art133-competencia","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"Constituição do Acre: competência da Polícia Civil","tested_topic":"Constituição do Estado do Acre, art. 133","difficulty":"média","official_answer":"E","question_text":"O art. 133 da Constituição do Estado do Acre caracteriza a Polícia Civil como instituição permanente, dirigida por Delegado de Polícia de carreira, e lhe atribui:\n\nA) exclusivamente policiamento ostensivo e patrulhamento fardado.\nB) segurança dos estabelecimentos penais.\nC) defesa civil e combate a incêndios.\nD) julgamento de infrações penais comuns.\nE) funções de polícia judiciária e apuração das infrações penais no território estadual, exceto as militares e ressalvada a competência da União.","explanation":"O art. 133 estadual atribui à Polícia Civil as funções de polícia judiciária e apuração das infrações penais em todo o Estado, exceto as militares e ressalvada a competência da União. O dispositivo também a caracteriza como instituição permanente, dirigida por Delegado de carreira.","legal_basis":["Constituição do Estado do Acre, art. 133"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Constituição do Estado do Acre, art. 133"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}},{"source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","syllabus_topic_id":"d204d14f-8aa6-4c57-92ad-3fb3c3e901f1","external_item_key":"pcac26-legis-312-cf144-seguranca-publica","contest_name":"Polícia Civil do Acre","contest_year":2026,"career_name":"Oficial Investigador de Polícia","exam_board":"IDECAN","subject":"Legislação Institucional","subtopic":"CF, art. 144: dever e responsabilidade pela segurança pública","tested_topic":"Constituição Federal, art. 144, caput","difficulty":"fácil","official_answer":"D","question_text":"A Constituição Federal estabelece que a segurança pública é:\n\nA) dever exclusivo dos municípios.\nB) responsabilidade exclusiva das polícias.\nC) dever apenas da União e direito apenas dos Estados.\nD) dever do Estado, direito e responsabilidade de todos.\nE) atribuição exclusiva das Forças Armadas.","explanation":"O caput do art. 144 dispõe que a segurança pública é dever do Estado, direito e responsabilidade de todos, destinada à preservação da ordem pública e da incolumidade das pessoas e do patrimônio.","legal_basis":["Constituição Federal, art. 144, caput"],"content_status":"active","is_original":true,"didactic_provenance":{"source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III, p. 64","legal_sources":["Constituição Federal, art. 144, caput"],"review_date":"2026-11-14","kind":"original_question","review_note":"Questão autoral, não oficial da banca; revisada contra legislação e jurisprudência indicadas."}}]$questions$::jsonb)
